        return map {
            $key eq lc $headers->[$i++] ? $headers->[$i++] : ++$i && ();
        } 1 .. @$headers/2;
    }

    while ($i < @$headers) {
        return $headers->[$i+1] if $key eq lc $headers->[$i];
        $i += 2;
    }

    ();
